    "shortDescription": "Семнадцать дней и шестнадцать ночей, наполненных посещением культурных достопримечательностей, наслаждением пейзажами горной местности, наблюдением за дикой природой и отдыхом на южных пляжах.",
    "overview": "Посетите Хабарану, Сигирию, Хиривадунну и Миннерию, совершите полет на воздушном шаре и побывайте в Анурадхапуре. Откройте для себя пещерный храм Дамбулла, Храм Зуба Будды в Канди, культурное представление, башню Амбулувава и Королевский ботанический сад. Продолжите путь через Нувара-Элию к водопаду Рамбода, озеру Грегори и клубничной ферме, а затем в Эллу, где вас ждут Мост девяти арок, «Мини-пик Адама» и водопад Равана. Южная часть маршрута включает национальный парк Яла, Мириссу, голландский форт в Галле, инкубатор морских черепах в Косгоде и круиз на закате в Бентоте. Завершите путешествие обзором достопримечательностей Коломбо, шопингом и дегустацией уличной еды.",
